/**
 * Names over players, drawn where Personal Space draws them, the way Player Indicators would.
 *
 * <p>RuneLite's Player Indicators puts a name over where a player really stands, which in a
 * spread-out crowd is the middle of the pile: everyone's name lands in one heap while their
 * bodies stand round it. Player Indicators can't be told where the bodies went, so this overlay
 * draws the same labels over the drawn bodies instead, reading Player Indicators' own settings
 * (who gets a name, each colour, rank icons) so that nothing changes but where the names sit.
 * Someone using it turns Player Indicators' own names off (its "Name position" set to Disabled)
 * or gets both.
 */
final class NamesOverlay extends Overlay
{
	/** Player Indicators' settings group. Two of its colour keys keep older names. */
	static final String PLAYER_INDICATORS = "playerindicators";

	/** A Player Indicators highlight setting: off, on, or only where you can be attacked. */
	enum Highlight
	{
		DISABLED,
		ENABLED,
		PVP
	}

	/** Player Indicators' choices: who gets a name and in what colour. Its defaults when unset. */
	static final class Look
	{
		Highlight own = Highlight.DISABLED;
		Highlight party = Highlight.ENABLED;
		Highlight friend = Highlight.ENABLED;
		Highlight friendsChat = Highlight.ENABLED;
		Highlight team = Highlight.ENABLED;
		Highlight clan = Highlight.ENABLED;
		Highlight others = Highlight.DISABLED;
		Color ownColour = new Color(0, 184, 212);
		Color partyColour = new Color(234, 123, 91);
		Color friendColour = new Color(0, 200, 83);
		Color friendsChatColour = new Color(170, 0, 255);
		Color teamColour = new Color(19, 110, 247);
		Color clanColour = new Color(36, 15, 171);
		Color othersColour = Color.RED;
		boolean friendsChatRanks = true;
		boolean clanRanks = true;

		/** Player Indicators' current settings, straight from RuneLite's settings store. */
		static Look read(ConfigManager configs)
		{
			Look look = new Look();
			look.own = highlight(configs, "highlightSelf", look.own);
			look.party = highlight(configs, "highlightPartyMembers", look.party);
			look.friend = highlight(configs, "highlightFriends", look.friend);
			look.friendsChat = highlight(configs, "highlightFriendsChat", look.friendsChat);
			look.team = highlight(configs, "highlightTeamMembers", look.team);
			look.clan = highlight(configs, "highlightClanMembers", look.clan);
			look.others = highlight(configs, "highlightOthers", look.others);
			look.ownColour = colour(configs, "ownNameColor", look.ownColour);
			look.partyColour = colour(configs, "partyMemberNameColor", look.partyColour);
			look.friendColour = colour(configs, "friendNameColor", look.friendColour);
			look.friendsChatColour = colour(configs, "clanMemberColor", look.friendsChatColour);
			look.teamColour = colour(configs, "teamMemberColor", look.teamColour);
			look.clanColour = colour(configs, "clanChatMemberColor", look.clanColour);
			look.othersColour = colour(configs, "nonClanMemberColor", look.othersColour);
			look.friendsChatRanks = flag(configs, "showFriendsChatRanks", look.friendsChatRanks);
			look.clanRanks = flag(configs, "showClanChatRanks", look.clanRanks);
			return look;
		}

		private static Highlight highlight(ConfigManager configs, String key, Highlight fallback)
		{
			String value = configs.getConfiguration(PLAYER_INDICATORS, key);
			if (value == null)
			{
				return fallback;
			}
			try
			{
				return Highlight.valueOf(value);
			}
			catch (IllegalArgumentException e)
			{
				return fallback;
			}
		}

		private static Color colour(ConfigManager configs, String key, Color fallback)
		{
			try
			{
				Color value = configs.getConfiguration(PLAYER_INDICATORS, key, Color.class);
				return value == null ? fallback : value;
			}
			catch (RuntimeException e)
			{
				return fallback;
			}
		}

		private static boolean flag(ConfigManager configs, String key, boolean fallback)
		{
			String value = configs.getConfiguration(PLAYER_INDICATORS, key);
			return value == null ? fallback : Boolean.parseBoolean(value);
		}
	}

	/** How far above the top of the model the name sits, as in Player Indicators. */
	private static final int ABOVE_HEAD = 40;
	/** The game's "in the Wilderness" and "PvP" flags, as Player Indicators reads them. */
	private static final int IN_WILDERNESS = 5963;
	private static final int PVP_SPEC_ORB = 8121;

	private final Client client;
	private final PersonalSpaceConfig config;
	private final ConfigManager configs;
	private final OffsetTable offsets;
	private final PartyService party;
	private final ChatIconManager icons;
	private final LevelFilter filter;

	/** Player Indicators' settings, re-read once a game tick. */
	private Look look;
	private int lookTick = -1;

	NamesOverlay(Client client, PersonalSpaceConfig config, ConfigManager configs, OffsetTable offsets, PartyService party, ChatIconManager icons, LevelFilter filter)
	{
		this.filter = filter;
		this.client = client;
		this.config = config;
		this.configs = configs;
		this.offsets = offsets;
		this.party = party;
		this.icons = icons;
		// Player Indicators draws on the default layer, above overhead chat and hitsplats; so does this.
		setPosition(OverlayPosition.DYNAMIC);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.namesFollowPlayers())
		{
			return null;
		}
		WorldView wv = client.getTopLevelWorldView();
		Player local = client.getLocalPlayer();
		if (wv == null || local == null)
		{
			return null;
		}
		int tick = client.getTickCount();
		if (look == null || tick != lookTick)
		{
			look = Look.read(configs);
			lookTick = tick;
		}
		boolean pvp = client.getVarbitValue(IN_WILDERNESS) == 1 || client.getVarbitValue(PVP_SPEC_ORB) == 1;
		draw(graphics, wv, local, pvp);
		for (WorldView boat : wv.worldViews())
		{
			if (boat != null)
			{
				draw(graphics, boat, local, pvp);
			}
		}
		return null;
	}

	/** Names over the players of one world: the main world, or a boat's deck. */
	private void draw(Graphics2D graphics, WorldView world, Player local, boolean pvp)
	{
		boolean inParty = look.party != Highlight.DISABLED && party.isInParty();
		for (Player player : world.players())
		{
			if (player == null || filter.hides(player))
			{
				continue;
			}
			String name = player.getName();
			LocalPoint at = player.getLocalLocation();
			if (name == null || at == null)
			{
				continue;
			}
			boolean you = player == local;
			boolean partyMember = !you && inParty && party.getMemberByDisplayName(name) != null;
			Color colour = colourFor(look, pvp, you, partyMember, player.isFriend(), player.isFriendsChatMember(),
				player.getTeam() != 0 && player.getTeam() == local.getTeam(), player.isClanMember());
			if (colour == null)
			{
				continue;
			}
			int dx = offsets.dx(player.getId());
			int dz = offsets.dz(player.getId());
			if (dx != 0 || dz != 0)
			{
				at = new LocalPoint(at.getX() + dx, at.getY() + dz, world);
			}
			// Off the edge of this world's tiles (a deck is only a few tiles across): no name.
			if (at.getSceneX() < 0 || at.getSceneY() < 0 || at.getSceneX() >= world.getSizeX() || at.getSceneY() >= world.getSizeY())
			{
				continue;
			}
			// The same sums as the game's own Actor.getCanvasTextLocation: the ground under the
			// player's footprint, less any lift from their animation, less the height of the name.
			Point foot;
			try
			{
				int ground = Perspective.getFootprintTileHeight(client, at, world.getPlane(), player.getFootprintSize())
					- player.getAnimationHeightOffset();
				foot = Perspective.localToCanvas(client, at.getWorldView(), at.getX(), at.getY(), ground - player.getLogicalHeight() - ABOVE_HEAD);
			}
			catch (RuntimeException e)
			{
				continue;
			}
			if (foot == null)
			{
				continue;
			}
			String shown = Text.sanitize(name);
			FontMetrics metrics = graphics.getFontMetrics();
			int width = (int) metrics.getStringBounds(shown, graphics).getWidth();
			Point where = new Point(foot.getX() - width / 2, foot.getY());
			BufferedImage rank = you ? null : rankImage(player, name);
			if (rank != null)
			{
				// Laid out as Player Indicators does: the icon to the left, the name nudged right.
				int textHeight = metrics.getHeight() - metrics.getMaxDescent();
				OverlayUtil.renderImageLocation(graphics,
					new Point(where.getX() - rank.getWidth() / 2 - 1, where.getY() - textHeight / 2 - rank.getHeight() / 2), rank);
				where = new Point(where.getX() + rank.getWidth() / 2, where.getY());
			}
			OverlayUtil.renderTextLocation(graphics, where, shown, colour);
		}
	}

	/** The friends chat or clan rank icon Player Indicators would show beside this name, or null. */
	private BufferedImage rankImage(Player player, String name)
	{
		try
		{
			if (look.friendsChatRanks && player.isFriendsChatMember())
			{
				FriendsChatManager chat = client.getFriendsChatManager();
				Nameable member = chat == null ? null : chat.findByName(Text.removeTags(name));
				if (member instanceof FriendsChatMember)
				{
					FriendsChatRank rank = ((FriendsChatMember) member).getRank();
					if (rank != null && rank != FriendsChatRank.UNRANKED)
					{
						return icons.getRankImage(rank);
					}
				}
			}
			if (look.clanRanks && player.isClanMember())
			{
				ClanChannel channel = client.getClanChannel();
				ClanSettings settings = client.getClanSettings();
				ClanChannelMember member = channel == null ? null : channel.findMember(Text.removeTags(name));
				if (member != null && settings != null)
				{
					ClanTitle title = settings.titleForRank(member.getRank());
					if (title != null)
					{
						return icons.getRankImage(title);
					}
				}
			}
		}
		catch (RuntimeException e)
		{
			// no icon, then
		}
		return null;
	}

	/**
	 * The colour a player's name gets, or null for no name: Player Indicators' own order and
	 * rules. You are only ever "you"; anyone else is the first of party, friend, friends chat,
	 * team, clan that they are and that is switched on, else "others" if that is on and they are
	 * in neither your friends chat nor your clan.
	 */
	static Color colourFor(Look look, boolean pvp, boolean you, boolean party, boolean friend, boolean friendsChat, boolean team, boolean clan)
	{
		if (you)
		{
			return on(look.own, pvp) ? look.ownColour : null;
		}
		if (party && on(look.party, pvp))
		{
			return look.partyColour;
		}
		if (friend && on(look.friend, pvp))
		{
			return look.friendColour;
		}
		if (friendsChat && on(look.friendsChat, pvp))
		{
			return look.friendsChatColour;
		}
		if (team && on(look.team, pvp))
		{
			return look.teamColour;
		}
		if (clan && on(look.clan, pvp))
		{
			return look.clanColour;
		}
		if (!friendsChat && !clan && on(look.others, pvp))
		{
			return look.othersColour;
		}
		return null;
	}

	static boolean on(Highlight setting, boolean pvp)
	{
		return setting == Highlight.ENABLED || (setting == Highlight.PVP && pvp);
	}
}

package com.grant9008.personalspace;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.geom.AffineTransform;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;
import net.runelite.client.util.Text;

/**
 * Hover a drawn body to see who it is.
 *
 * <p>Clicking stays with the game: you click people where they really stand, because a plugin
 * may not move a click zone. But you can be told who you're looking at. With the mouse over a
 * body drawn away from its tile, a tooltip gives the name and combat level, and a small arrow
 * points from the body to where they really stand. Each is its own switch.
 */
final class HoverOverlay extends Overlay
{
	/** The arrow from the body to where they really are. */
	private static final Color ARROW = new Color(255, 232, 0, 200);
	private static final BasicStroke ARROW_STROKE = new BasicStroke(2f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND);
	/** Closer than this on the screen and the arrow would be a smudge: they're standing right there. */
	private static final int ARROW_MIN = 24;

	private final Client client;
	private final PersonalSpaceConfig config;
	private final OffsetTable offsets;
	private final StackRegistry stacks;
	private final TooltipManager tooltips;
	private final LevelFilter filter;

	/** Where the hovered body's feet and its real tile are on the screen this frame. */
	private Point hoveredFeet;
	private Point hoveredReal;

	HoverOverlay(Client client, PersonalSpaceConfig config, OffsetTable offsets, StackRegistry stacks, TooltipManager tooltips, LevelFilter filter)
	{
		this.filter = filter;
		this.client = client;
		this.config = config;
		this.offsets = offsets;
		this.stacks = stacks;
		this.tooltips = tooltips;
		setPosition(OverlayPosition.DYNAMIC);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		boolean who = config.hoverShowsWho();
		boolean arrow = config.hoverArrow();
		if ((!who && !arrow) || client.isMenuOpen())
		{
			return null;
		}
		WorldView top = client.getTopLevelWorldView();
		Player local = client.getLocalPlayer();
		Point mouse = client.getMouseCanvasPosition();
		if (top == null || local == null || mouse == null || mouse.getX() < 0)
		{
			return null;
		}
		hoveredFeet = null;
		hoveredReal = null;
		Player best = nearestUnderMouse(top, local, mouse, null);
		for (WorldView boat : top.worldViews())
		{
			if (boat != null)
			{
				best = nearestUnderMouse(boat, local, mouse, best);
			}
		}
		if (best == null)
		{
			return null;
		}
		String name = best.getName();
		if (who && name != null)
		{
			tooltips.add(new Tooltip(Text.sanitize(name) + "  <col=" + levelColour(local.getCombatLevel(), best.getCombatLevel())
				+ ">(level-" + best.getCombatLevel() + ")</col>"));
		}
		if (arrow && hoveredFeet != null && hoveredReal != null)
		{
			arrow(graphics, hoveredFeet, hoveredReal);
		}
		return null;
	}

	/** Of this world's players drawn away from where they stand, the one under the mouse nearest the camera. */
	private Player nearestUnderMouse(WorldView world, Player local, Point mouse, Player best)
	{
		int mx = mouse.getX();
		int my = mouse.getY();
		int bestY = hoveredFeet == null ? Integer.MIN_VALUE : hoveredFeet.getY();
		for (Player p : world.players())
		{
			if (p == null || p == local || filter.hides(p))
			{
				continue;
			}
			int id = p.getId();
			LocalPoint lp = p.getLocalLocation();
			if (lp == null)
			{
				continue;
			}
			int plane = p.getWorldLocation() == null ? world.getPlane() : p.getWorldLocation().getPlane();
			int dx = offsets.dx(id);
			int dz = offsets.dz(id);
			boolean away = dx != 0 || dz != 0;
			if (!away)
			{
				// Standing where they're drawn: the game's own hover text names them, unless they
				// are one of several in a tile's middle, where only the first is drawn at all.
				long tile = StackRegistry.key(StackRegistry.layer(world.getId(), plane), lp.getSceneX(), lp.getSceneY());
				if (stacks.membersAt(tile).length == 0 || stacks.isUnplaced(id))
				{
					continue;
				}
			}
			LocalPoint drawn = away ? new LocalPoint(lp.getX() + dx, lp.getY() + dz, world) : lp;
			if (drawn.getSceneX() < 0 || drawn.getSceneY() < 0 || drawn.getSceneX() >= world.getSizeX() || drawn.getSceneY() >= world.getSizeY())
			{
				continue;
			}
			Point feet;
			Point head;
			Point realFeet;
			try
			{
				feet = Perspective.localToCanvas(client, drawn, plane);
				head = Perspective.localToCanvas(client, drawn, plane, p.getLogicalHeight());
				realFeet = away ? Perspective.localToCanvas(client, lp, plane) : feet;
			}
			catch (RuntimeException e)
			{
				continue;
			}
			if (feet == null || head == null || feet.getY() <= bestY)
			{
				continue;
			}
			// A quick look first: roughly a body's box on the screen.
			int height = feet.getY() - head.getY();
			int halfWidth = Math.max(12, height / 3);
			if (height <= 0 || mx < feet.getX() - halfWidth || mx > feet.getX() + halfWidth || my < head.getY() || my > feet.getY())
			{
				continue;
			}
			// Then the model's real outline, slid from where they stand to where they're drawn.
			boolean hit = true;
			try
			{
				Shape hull = p.getConvexHull();
				if (hull != null && realFeet != null)
				{
					Shape slid = AffineTransform.getTranslateInstance(feet.getX() - realFeet.getX(), feet.getY() - realFeet.getY())
						.createTransformedShape(hull);
					hit = slid.contains(mx, my);
				}
			}
			catch (RuntimeException e)
			{
				// the box will do
			}
			if (hit)
			{
				best = p;
				bestY = feet.getY();
				hoveredFeet = feet;
				hoveredReal = away ? realFeet : null;
			}
		}
		return best;
	}

	/**
	 * The colour the game gives "(level-N)" beside a name: green for someone well below you,
	 * through yellow for your own level, to red for someone well above.
	 */
	static String levelColour(int yours, int theirs)
	{
		int diff = theirs - yours;
		if (diff < -9)
		{
			return "00ff00";
		}
		if (diff < -6)
		{
			return "40ff00";
		}
		if (diff < -3)
		{
			return "80ff00";
		}
		if (diff < 0)
		{
			return "c0ff00";
		}
		if (diff > 9)
		{
			return "ff0000";
		}
		if (diff > 6)
		{
			return "ff3000";
		}
		if (diff > 3)
		{
			return "ff7000";
		}
		if (diff > 0)
		{
			return "ffb000";
		}
		return "ffff00";
	}

	/** A small arrow from the drawn body's feet to where they really stand. */
	private static void arrow(Graphics2D graphics, Point from, Point to)
	{
		double dx = to.getX() - from.getX();
		double dy = to.getY() - from.getY();
		double length = Math.hypot(dx, dy);
		if (length < ARROW_MIN)
		{
			return;
		}
		double ux = dx / length;
		double uy = dy / length;
		int x1 = (int) Math.round(from.getX() + ux * 8);
		int y1 = (int) Math.round(from.getY() + uy * 8);
		int x2 = (int) Math.round(to.getX() - ux * 3);
		int y2 = (int) Math.round(to.getY() - uy * 3);
		Object aa = graphics.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		graphics.setColor(ARROW);
		graphics.setStroke(ARROW_STROKE);
		graphics.drawLine(x1, y1, x2, y2);
		double angle = Math.atan2(dy, dx);
		Polygon head = new Polygon();
		head.addPoint(x2, y2);
		head.addPoint((int) Math.round(x2 - 9 * Math.cos(angle - 0.45)), (int) Math.round(y2 - 9 * Math.sin(angle - 0.45)));
		head.addPoint((int) Math.round(x2 - 9 * Math.cos(angle + 0.45)), (int) Math.round(y2 - 9 * Math.sin(angle + 0.45)));
		graphics.fillPolygon(head);
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, aa == null ? RenderingHints.VALUE_ANTIALIAS_DEFAULT : aa);
	}
}

package com.grant9008.personalspace;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * The geometry of a crowded tile: where its spots are, which way a group faces, and which way a
 * moved player should turn. Knows nothing about RuneLite so it can be unit tested on its own.
 *
 * <p>Two shapes (chosen by {@link ShapeMemory}):
 * <ul>
 * <li><b>Row</b>: side by side in front of the thing everyone faces. Around an anvil, range or fire
 * the row curves round it; along a bank counter it runs straight.</li>
 * <li><b>Crowd</b>: rings around the tile, for players facing every which way.</li>
 * </ul>
 */
final class StackSpreader
{
	/** Orientation units in a full turn, as used by the game. 0 faces south, 512 west, 1024 north, 1536 east. */
	static final int FULL_TURN = 2048;

	/** How closely a group's facings must agree to count as "facing the same way" (about 25 degrees either side). */
	static final double SAME_FACING = 0.9;
	/** A tile already in a row stays a row until facings disagree by more than this (about 45 degrees), so it doesn't flip back and forth. */
	static final double STILL_SAME_FACING = 0.7;

	/** How far ahead of a player the thing they're facing is assumed to be: the next tile over. */
	static final int LOOK_AHEAD = 128;

	/** Most a curved row turns between neighbours is this divided by {@link #ARC_REACH}: 28 degrees. */
	static final double MAX_ARC = Math.toRadians(70);
	/**
	 * How far round what everyone faces a curved row may wrap either side of straight ahead
	 * (135 degrees). People gather all the way round a tree, fire or anvil before anyone has to stand
	 * behind someone else, where an axe or hammer would look like it's swinging at them.
	 */
	static final double WRAP_ARC = Math.toRadians(135);

	/** Most players in one straight row before the next row starts. */
	static final int ROW_WIDTH = 8;
	/** Most players in one curved row before the next row starts. */
	static final int CURVED_ROW_WIDTH = 10;
	private static final int ROWS = 3;
	/** Furthest a row stands behind the row in front, whatever the spacing: just under a tile. */
	static final int ROW_DEPTH = 112;
	/** Spacings used to size the largest turn between curved-row neighbours; see {@link #MAX_ARC}. */
	static final double ARC_REACH = 2.5;
	/** Furthest a straight row reaches either side of the middle, in spacings: a little further, so a row blocked on one side can grow along the other. */
	static final double STRAIGHT_REACH = 3.5;
	/** Crowd spots, best first: an inner ring, the middle, then an outer ring. Opposite sides alternate so any number looks balanced. */
	private static final double[] INNER_RING = {0, 180, 120, 300, 60, 240};
	private static final double[] OUTER_RING = {30, 210, 150, 330, 90, 270, 0, 180, 60, 240, 120, 300};
	static final int CROWD_PATTERN_SIZE = INNER_RING.length + 1 + OUTER_RING.length;

	/** Where a spot can be, relative to the tile centre. */
	interface SpotCheck
	{
		boolean canStand(int dx, int dz);
	}

	/** Furthest a player is placed from the tile centre along a line, in local units (three tiles). */
	static final int MAX_LINE_EXTENT = 384;
	/** Furthest back from its middle a bowed counter row reaches, in local units. */
	static final int MAX_BOW = 48;
	/**
	 * The circle a bowed row follows, in local units: two and a half tiles across, so the whole row
	 * is one gentle curve round the booth. A tighter one, eased into straight lines to keep rows
	 * apart, drew a row as a V: the further along, the further from the counter.
	 */
	static final int BOW_RADIUS = 320;
	/** How far along the row the curve goes before it is {@link #MAX_BOW} back and stays there. */
	static final double BOW_REACH = Math.sqrt(2.0 * BOW_RADIUS * MAX_BOW - (double) MAX_BOW * MAX_BOW);
	/**
	 * Steepest the bow gets, where it levels off. A row behind stands half a spacing along from the
	 * one in front, where the row in front has bowed away from it by up to this much per unit, so
	 * each row behind gets that much more depth to keep the gap between them.
	 */
	static final double BOW_SLOPE = BOW_REACH / (BOW_RADIUS - MAX_BOW);

	/** One standing-still player on a tile. */
	static final class Entry
	{
		final int id;
		final long tile;
		final boolean local;
		/** Facing in game orientation units, or -1 if unknown. */
		final int orientation;
		/** Busy with something (alching, smithing, an emote) a moment ago. */
		final boolean busy;

		Entry(int id, long tile, boolean local)
		{
			this(id, tile, local, -1);
		}

		Entry(int id, long tile, boolean local, int orientation)
		{
			this(id, tile, local, orientation, false);
		}

		Entry(int id, long tile, boolean local, int orientation, boolean busy)
		{
			this.id = id;
			this.tile = tile;
			this.local = local;
			this.orientation = orientation;
			this.busy = busy;
		}
	}

	/** Where one player should be drawn relative to their real spot, in local units (x east, z north). */
	static final class Placement
	{
		final int id;
		final long tile;
		final int dx;
		final int dz;

		Placement(int id, long tile, int dx, int dz)
		{
			this.id = id;
			this.tile = tile;
			this.dx = dx;
			this.dz = dz;
		}
	}

	private StackSpreader()
	{
	}

	/**
	 * The usable spots for a tile, best first, at most {@code capacity} of them. The pattern never
	 * depends on how many players there are, so adding or removing a player never moves anyone
	 * else's spot. Spots a player couldn't stand on (a booth, stall, anvil or wall) are skipped.
	 *
	 * <p>Rows: a front row, then a row behind it, then another, up to {@link #ROW_WIDTH} usable spots
	 * each in a straight row and {@link #CURVED_ROW_WIDTH} in a curved one, which wraps up to
	 * {@link #WRAP_ARC} round what everyone faces before a row behind is started. The front row starts half a spacing either side of the middle, so two players share the
	 * space in front of what they face evenly, and it grows outwards from there. When someone who
	 * stays put stands in the middle, the front row leaves them a full spacing of room instead. Each
	 * row behind stands in the gaps of the row in front. A row curves around what everyone faces,
	 * except at a counter ({@code straight}), where it runs straight along it.
	 *
	 * <p>Crowds: an inner ring, the middle, then an outer ring.
	 */
	static List<int[]> spots(boolean row, boolean straight, double angle, boolean middleTaken, int spacing, int capacity, SpotCheck check)
	{
		return spots(row, straight, angle, middleTaken, spacing, capacity, check, LOOK_AHEAD);
	}

	/** As above, on a curve of {@code arcRadius}; see {@link #arcRadius(int, boolean)}. */
	static List<int[]> spots(boolean row, boolean straight, double angle, boolean middleTaken, int spacing, int capacity,
		SpotCheck check, int arcRadius)
	{
		return spots(row, straight, angle, middleTaken, spacing, capacity, check, arcRadius, false);
	}

	/** As above; {@code bow} curves a straight row gently round what it stands along. */
	static List<int[]> spots(boolean row, boolean straight, double angle, boolean middleTaken, int spacing, int capacity,
		SpotCheck check, int arcRadius, boolean bow)
	{
		return spots(row, straight, angle, middleTaken, spacing, capacity, check, arcRadius, bow, WRAP_ARC);
	}

	/** As above, wrapping {@code wrap} round what everyone faces before a row behind is started. */
	static List<int[]> spots(boolean row, boolean straight, double angle, boolean middleTaken, int spacing, int capacity,
		SpotCheck check, int arcRadius, boolean bow, double wrap)
	{
		List<int[]> out = new ArrayList<>(capacity);
		if (!row)
		{
			for (int i = 0; i < CROWD_PATTERN_SIZE && out.size() < capacity; i++)
			{
				if (middleTaken && i == INNER_RING.length)
				{
					continue;
				}
				int[] spot = crowdSpot(i, spacing);
				if (check == null || check.canStand(spot[0], spot[1]))
				{
					out.add(spot);
				}
			}
			return out;
		}

		double reach = straight ? STRAIGHT_REACH : wrap / curvedTurn(spacing, arcRadius) + 1e-9;
		int width = straight ? ROW_WIDTH : CURVED_ROW_WIDTH;
		// Which side of the middle a row fills first. The ring pattern always starts on the east
		// side, so a row does too where it can: a pair then keeps its places when their tile changes
		// between a ring and a row, instead of the two of them swapping sides for no reason.
		double alongX = -Math.cos(angle);
		int first = (Math.abs(alongX) > 1e-9 ? alongX : Math.sin(angle)) >= 0 ? 1 : -1;
		for (int rowNumber = 0; rowNumber < ROWS && out.size() < capacity; rowNumber++)
		{
			// Rows take turns between spots off the middle line and spots on it, so each row
			// stands in the gaps of the one in front.
			boolean offMiddle = (rowNumber % 2 == 0) != middleTaken;
			int inRow = 0;
			for (double step = offMiddle ? 0.5 : 0; step <= reach && inRow < width && out.size() < capacity; step++)
			{
				for (int side = 0; side < (step == 0 ? 1 : 2) && inRow < width && out.size() < capacity; side++)
				{
					if (step == 0 && rowNumber == 0 && middleTaken)
					{
						continue;
					}
					int[] spot = rowSpot(rowNumber, first * (side == 0 ? step : -step), straight, angle, spacing, arcRadius, bow);
					if (spot != null && (check == null || check.canStand(spot[0], spot[1])))
					{
						out.add(spot);
						inRow++;
					}
				}
			}
		}
		return out;
	}

	/**
	 * The spot {@code step} spacings along row {@code rowNumber} (0 is the front row), relative to the
	 * tile centre, or null if that is further out than a row may reach.
	 *
	 * <p>A curved row keeps everyone the same distance from what they face ({@link #LOOK_AHEAD}
	 * ahead of the tile centre, plus a row depth for each row behind). Front-row neighbours are about
	 * {@code spacing} apart along the curve, but never more than {@link #MAX_ARC} / {@link #ARC_REACH}
	 * round from each other; rows behind
	 * keep the same angle between neighbours, so their half-step offsets land in the gaps. A straight
	 * row runs sideways across the facing, each row behind a row depth further back.
	 */
	static int[] rowSpot(int rowNumber, double step, boolean straight, double angle, int spacing)
	{
		return rowSpot(rowNumber, step, straight, angle, spacing, LOOK_AHEAD);
	}

	/** As above, on a curve of {@code arcRadius}; see {@link #arcRadius(int, boolean)}. */
	static int[] rowSpot(int rowNumber, double step, boolean straight, double angle, int spacing, int arcRadius)
	{
		return rowSpot(rowNumber, step, straight, angle, spacing, arcRadius, false);
	}

	/** As above; {@code bow} curves a straight row gently round what it stands along. */
	static int[] rowSpot(int rowNumber, double step, boolean straight, double angle, int spacing, int arcRadius, boolean bow)
	{
		double fwdX = -Math.sin(angle);
		double fwdZ = -Math.cos(angle);
		// A row behind stands half a spacing along from the one in front, so where the row in front
		// has bowed away from it the gap between the two closes. Give every row behind that much
		// more depth and the two of them stay exactly as far apart as they were before the bow.
		double depth = rowNumber * (Math.min(spacing, ROW_DEPTH) + (bow ? BOW_SLOPE * spacing / 2 : 0));
		if (straight)
		{
			double along = step * spacing;
			if (Math.abs(along) > MAX_LINE_EXTENT)
			{
				return null;
			}
			double back = depth + (bow ? bowBack(along) : 0);
			double x = fwdZ * along - fwdX * back;
			double z = -fwdX * along - fwdZ * back;
			return new int[]{(int) Math.round(x), (int) Math.round(z)};
		}
		double radius = arcRadius + depth;
		double phi = step * curvedTurn(spacing, arcRadius);
		double focusX = fwdX * arcRadius;
		double focusZ = fwdZ * arcRadius;
		double backX = -fwdX * radius;
		double backZ = -fwdZ * radius;
		double x = focusX + backX * Math.cos(phi) - backZ * Math.sin(phi);
		double z = focusZ + backX * Math.sin(phi) + backZ * Math.cos(phi);
		if (arcRadius > LOOK_AHEAD && Math.hypot(x, z) > MAX_LINE_EXTENT)
		{
			// A curve opened out by the slider still reaches no further than a row does.
			return null;
		}
		return new int[]{(int) Math.round(x), (int) Math.round(z)};
	}

	/**
	 * How far back from the middle of a bowed row a spot {@code along} it stands, so a crowd at a
	 * bank booth curves gently round it instead of standing in a flat line: one circle of
	 * {@link #BOW_RADIUS}, levelling off at {@link #MAX_BOW} so a very long row doesn't curl away.
	 */
	static int bowBack(double along)
	{
		double d = Math.min(Math.abs(along), BOW_REACH);
		return (int) Math.round(Math.min(MAX_BOW, BOW_RADIUS - Math.sqrt(BOW_RADIUS * (double) BOW_RADIUS - d * d)));
	}

	/** The angle between neighbours in a curved row, in radians. */
	static double curvedTurn(int spacing)
	{
		return curvedTurn(spacing, LOOK_AHEAD);
	}

	/** The angle between neighbours in a curved row of {@code arcRadius}, in radians. */
	static double curvedTurn(int spacing, int arcRadius)
	{
		return Math.min((double) spacing / arcRadius, MAX_ARC / ARC_REACH);
	}

	/**
	 * The circle a curved row stands on. Normally {@link #LOOK_AHEAD}, so the curve hugs whatever
	 * everyone is facing: an anvil, a tree, a fire. Neighbours are then never more than
	 * {@link #MAX_ARC} / {@link #ARC_REACH} round from each other, which is about half a tile apart,
	 * however wide the spacing slider is set.
	 *
	 * <p>With {@code wide} - auto-spacing off, so the slider is in charge - the circle grows instead
	 * of the turn, until neighbours stand a full spacing apart. The curve opens out into a wide
	 * crescent rather than stopping at half a tile.
	 */
	static int arcRadius(int spacing, boolean wide)
	{
		return wide ? Math.max(LOOK_AHEAD, (int) Math.ceil(spacing / (MAX_ARC / ARC_REACH))) : LOOK_AHEAD;
	}

	/** Crowd spot {@code index}, relative to the tile centre: an inner ring, the middle, then an outer ring. */
	private static int[] crowdSpot(int index, int spacing)
	{
		if (index < INNER_RING.length)
		{
			return polar(0.8 * spacing, INNER_RING[index]);
		}
		if (index == INNER_RING.length)
		{
			return new int[]{0, 0};
		}
		return polar(Math.min(1.6 * spacing, MAX_LINE_EXTENT), OUTER_RING[index - INNER_RING.length - 1]);
	}

	private static int[] polar(double radius, double degrees)
	{
		double a = Math.toRadians(degrees);
		return new int[]{(int) Math.round(radius * Math.cos(a)), (int) Math.round(radius * Math.sin(a))};
	}

	/** True for the names of fires people gather round: a fire someone lit, a campfire, a fire pit. Not fireplaces. */
	static boolean isFireName(String name)
	{
		if (name == null)
		{
			return false;
		}
		String n = name.toLowerCase();
		return n.contains("fire") && !n.contains("fireplace");
	}

	/** How many tiles have two or more of the given players on them. */
	static int stackedTiles(List<Entry> entries)
	{
		Map<Long, Integer> counts = new LinkedHashMap<>();
		int stacked = 0;
		for (Entry e : entries)
		{
			if (counts.merge(e.tile, 1, Integer::sum) == 2)
			{
				stacked++;
			}
		}
		return stacked;
	}

	/**
	 * The direction the whole group faces, in radians (game convention: 0 south, pi/2 west), or
	 * null if their facings are unknown or don't agree to at least {@code needed} (1 is identical).
	 */
	static Double sharedFacing(List<Entry> group, double needed)
	{
		double sumX = 0;
		double sumZ = 0;
		for (Entry e : group)
		{
			if (e.orientation < 0)
			{
				return null;
			}
			double a = toRadians(e.orientation);
			sumX += -Math.sin(a);
			sumZ += -Math.cos(a);
		}
		double agreement = Math.hypot(sumX, sumZ) / group.size();
		if (agreement < needed)
		{
			return null;
		}
		return Math.atan2(-sumX, -sumZ);
	}

	/**
	 * Which way a player moved by (dx, dz) should face to keep looking at the same spot they were
	 * looking at from their real position, {@link #LOOK_AHEAD} in front of them. So the players at
	 * the ends of a row at an anvil turn in towards the anvil instead of staring past it.
	 */
	static int faceSameSpot(int orientation, int dx, int dz)
	{
		if (dx == 0 && dz == 0)
		{
			return orientation;
		}
		double a = toRadians(orientation);
		double lookX = -Math.sin(a) * LOOK_AHEAD - dx;
		double lookZ = -Math.cos(a) * LOOK_AHEAD - dz;
		if (Math.hypot(lookX, lookZ) < 1)
		{
			return orientation;
		}
		return OffsetTable.facing(lookX, lookZ);
	}

	/**
	 * Which way a player drawn at (dx, dz) from the tile centre should face to look at the point
	 * (focusX, focusZ), also relative to the tile centre; {@code orientation} if they're standing on it.
	 */
	static int faceTowards(int orientation, int dx, int dz, int focusX, int focusZ)
	{
		double lookX = focusX - dx;
		double lookZ = focusZ - dz;
		if (Math.hypot(lookX, lookZ) < 1)
		{
			return orientation;
		}
		return OffsetTable.facing(lookX, lookZ);
	}

	/** The orientation halfway round from {@code from} to {@code to}, the short way. */
	static int halfway(int from, int to)
	{
		int diff = ((to - from) % FULL_TURN + FULL_TURN + FULL_TURN / 2) % FULL_TURN - FULL_TURN / 2;
		return ((from + diff / 2) % FULL_TURN + FULL_TURN) % FULL_TURN;
	}

	static double toRadians(int orientation)
	{
		return 2 * Math.PI * (((orientation % FULL_TURN) + FULL_TURN) % FULL_TURN) / FULL_TURN;
	}

}

