	/** An on/off switch drawn in RuneLite's colours. Fires only on a user click. */
	private static final class ToggleSwitch extends JComponent
	{
		private static final int W = 32;
		private static final int H = 18;
		private boolean on;
		private Consumer<Boolean> listener = v ->
		{
		};

		ToggleSwitch()
		{
			setPreferredSize(new Dimension(W, H));
			setMinimumSize(new Dimension(W, H));
			setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
			addMouseListener(new MouseAdapter()
			{
				@Override
				public void mouseClicked(MouseEvent e)
				{
					click();
				}
			});
		}

		void onToggle(Consumer<Boolean> listener)
		{
			this.listener = listener;
		}

		void setOn(boolean on)
		{
			if (this.on != on)
			{
				this.on = on;
				repaint();
			}
		}

		void click()
		{
			if (!isEnabled())
			{
				return;
			}
			on = !on;
			repaint();
			listener.accept(on);
		}

		@Override
		public void setEnabled(boolean enabled)
		{
			super.setEnabled(enabled);
			repaint();
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			Graphics2D g2 = (Graphics2D) g.create();
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			int y = (getHeight() - H) / 2;
			int x = getWidth() - W;
			Color track = on ? ColorScheme.BRAND_ORANGE : ColorScheme.MEDIUM_GRAY_COLOR;
			if (!isEnabled())
			{
				track = track.darker().darker();
			}
			g2.setColor(track);
			g2.fillRoundRect(x, y, W, H, H, H);
			int knob = H - 4;
			int knobX = on ? x + W - knob - 2 : x + 2;
			g2.setColor(isEnabled() ? Color.WHITE : ColorScheme.LIGHT_GRAY_COLOR);
			g2.fillOval(knobX, y + 2, knob, knob);
			g2.dispose();
		}
	}

	/** A row of buttons where exactly one is picked. Fires only on a user click. */
	private static final class PillGroup<T> extends JPanel
	{
		private final T[] values;
		private final JLabel[] pills;
		private int selected = -1;
		private int hovered = -1;
		private Consumer<T> listener = v ->
		{
		};

		PillGroup(T[] values, String[] labels)
		{
			super(new GridLayout(1, values.length, 4, 0));
			setOpaque(false);
			this.values = values;
			this.pills = new JLabel[values.length];
			for (int i = 0; i < values.length; i++)
			{
				final int index = i;
				JLabel pill = new JLabel(labels[i], SwingConstants.CENTER);
				pill.setOpaque(true);
				pill.setFont(FontManager.getRunescapeSmallFont());
				pill.setBorder(new EmptyBorder(6, 2, 6, 2));
				pill.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
				pill.addMouseListener(new MouseAdapter()
				{
					@Override
					public void mouseClicked(MouseEvent e)
					{
						if (!PillGroup.this.isEnabled())
						{
							return;
						}
						select(PillGroup.this.values[index]);
						listener.accept(PillGroup.this.values[index]);
					}

					@Override
					public void mouseEntered(MouseEvent e)
					{
						hovered = index;
						restyle();
					}

					@Override
					public void mouseExited(MouseEvent e)
					{
						hovered = -1;
						restyle();
					}
				});
				pills[i] = pill;
				add(pill);
			}
			restyle();
		}

		void onSelect(Consumer<T> listener)
		{
			this.listener = listener;
		}

		void select(T value)
		{
			for (int i = 0; i < values.length; i++)
			{
				if (values[i].equals(value))
				{
					selected = i;
				}
			}
			restyle();
		}

		/** Like {@link #select}, but highlights nothing if the value isn't one of the buttons. */
		void selectOrNone(T value)
		{
			selected = -1;
			select(value);
		}

		@Override
		public void setToolTipText(String text)
		{
			super.setToolTipText(text);
			for (JLabel pill : pills)
			{
				pill.setToolTipText(text);
			}
		}

		@Override
		public void setEnabled(boolean enabled)
		{
			super.setEnabled(enabled);
			restyle();
		}

		private void restyle()
		{
			for (int i = 0; i < pills.length; i++)
			{
				Color bg;
				Color fg;
				if (i == selected)
				{
					bg = ColorScheme.BRAND_ORANGE;
					fg = SELECTED_TEXT;
				}
				else if (i == hovered && isEnabled())
				{
					bg = ColorScheme.MEDIUM_GRAY_COLOR;
					fg = Color.WHITE;
				}
				else
				{
					bg = ColorScheme.DARK_GRAY_COLOR;
					fg = ColorScheme.LIGHT_GRAY_COLOR;
				}
				if (!isEnabled())
				{
					bg = bg.darker();
					fg = fg.darker();
				}
				pills[i].setBackground(bg);
				pills[i].setForeground(fg);
			}
		}
	}

	/** A small filled circle, used as a status light. */
	private static final class Dot implements Icon
	{
		private final Color color;
		private final int size;

		Dot(Color color, int size)
		{
			this.color = color;
			this.size = size;
		}

		@Override
		public void paintIcon(Component c, Graphics g, int x, int y)
		{
			Graphics2D g2 = (Graphics2D) g.create();
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g2.setColor(color);
			g2.fillOval(x, y, size, size);
			g2.dispose();
		}

		@Override
		public int getIconWidth()
		{
			return size;
		}

		@Override
		public int getIconHeight()
		{
			return size;
		}
	}

	/** A small chevron: pointing right when folded, down when open. */
	private static final class Arrow implements Icon
	{
		private final boolean open;

		Arrow(boolean open)
		{
			this.open = open;
		}

		@Override
		public void paintIcon(Component c, Graphics g, int x, int y)
		{
			Graphics2D g2 = (Graphics2D) g.create();
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g2.setColor(ColorScheme.LIGHT_GRAY_COLOR);
			g2.setStroke(new BasicStroke(1.6f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			if (open)
			{
				g2.drawPolyline(new int[]{x + 1, x + 4, x + 7}, new int[]{y + 3, y + 6, y + 3}, 3);
			}
			else
			{
				g2.drawPolyline(new int[]{x + 3, x + 6, x + 3}, new int[]{y + 1, y + 4, y + 7}, 3);
			}
			g2.dispose();
		}

		@Override
		public int getIconWidth()
		{
			return 8;
		}

		@Override
		public int getIconHeight()
		{
			return 8;
		}
	}

	/** A small heart. */
	private static final class HeartIcon implements Icon
	{
		private final Color color;

		HeartIcon(Color color)
		{
			this.color = color;
		}

		@Override
		public void paintIcon(Component c, Graphics g, int x, int y)
		{
			Graphics2D g2 = (Graphics2D) g.create();
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g2.setColor(color);
			Path2D heart = new Path2D.Double();
			heart.moveTo(x + 7, y + 12);
			heart.curveTo(x - 2, y + 6, x + 1, y - 1, x + 7, y + 3);
			heart.curveTo(x + 13, y - 1, x + 16, y + 6, x + 7, y + 12);
			heart.closePath();
			g2.fill(heart);
			g2.dispose();
		}

		@Override
		public int getIconWidth()
		{
			return 14;
		}

		@Override
		public int getIconHeight()
		{
			return 13;
		}
	}
}

package com.grant9008.personalspace;

import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.Renderable;
import net.runelite.client.callback.RenderCallback;

/**
 * Hides players below a combat level you choose: the Grand Exchange's level-3 crowd, say.
 *
 * <p>Works the way RuneLite's own Entity Hider does, through a render callback: a hidden player
 * isn't drawn, nor is their overhead chat, health bar or hitsplats, can't be clicked, and so
 * isn't given a spot in a crowd either (the rest of the
 * plugin only lays out players the render callbacks allow). Friends, friends chat and clan
 * members are never hidden, nor are you. It is off unless a level is set, and it switches off
 * with the rest of the plugin in PvP areas and while you fight.
 */
final class LevelFilter implements RenderCallback
{
	private final Client client;

	/** Set by the plugin each tick: whether the plugin is running here and now. */
	volatile boolean enabled;
	/** Set by the plugin each tick: hide players below this combat level; 0 is off. */
	volatile int below;

	LevelFilter(Client client)
	{
		this.client = client;
	}

	@Override
	public boolean addEntity(Renderable renderable, boolean drawingUI)
	{
		// Asked twice for each player: for the body, and (drawingUI) for what's drawn over it,
		// their overhead chat, health bar and hitsplats. Both go, or a hidden casino bot's spam
		// still floated over the empty spot where it stood.
		if (!(renderable instanceof Player))
		{
			return true;
		}
		return !hides((Player) renderable);
	}

	/** Whether this player is hidden right now. */
	boolean hides(Player player)
	{
		if (!enabled || below <= 0 || player == null || player == client.getLocalPlayer())
		{
			return false;
		}
		return hides(below, player.getCombatLevel(), player.isFriend(), player.isFriendsChatMember(), player.isClanMember());
	}

	/** The rule itself: below the level, and not a friend, friends chat or clan member. */
	static boolean hides(int below, int level, boolean friend, boolean friendsChat, boolean clan)
	{
		return below > 0 && level > 0 && level < below && !friend && !friendsChat && !clan;
	}
}

package com.grant9008.personalspace;

import java.util.LinkedHashSet;
import java.util.Set;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.MessageNode;
import net.runelite.api.Player;
import net.runelite.api.WorldView;
import net.runelite.client.util.Text;

/**
 * Drops public chat from players the level filter hides: a hidden casino bot's spam went with its
 * body and its overhead text, but still filled the chat box.
 *
 * <p>Uses the same hook as RuneLite's Chat Filter, the {@code chatFilterCheck} script callback,
 * which asks, as each chat line is built, whether to show it. Someone hidden when they speak is
 * remembered for the session, by name, so their lines stay hidden after they walk out of view.
 * Nothing is saved or sent anywhere; turning the filter off shows everything again.
 */
final class ChatHider
{
	/** People remembered, at most: older names drop off first. */
	static final int REMEMBERED = 500;

	private final Client client;
	private final LevelFilter filter;
	private final Set<String> hiddenSpeakers = new LinkedHashSet<>();

	ChatHider(Client client, LevelFilter filter)
	{
		this.client = client;
		this.filter = filter;
	}

	/** Whether a chat line of this type from this sender should be dropped now. Client thread. */
	boolean drops(ChatMessageType type, String sender)
	{
		if (!isPublic(type) || sender == null || !filter.enabled || filter.below <= PersonalSpaceConfig.MIN_HIDE_BELOW)
		{
			return false;
		}
		String name = standard(sender);
		if (hiddenSpeakers.contains(name))
		{
			return true;
		}
		Player speaker = find(name);
		if (speaker != null && filter.hides(speaker))
		{
			remember(name);
			return true;
		}
		return false;
	}

	/** Called from the chat filter hook: blank the line if it's one to drop. */
	void check()
	{
		int[] ints = client.getIntStack();
		int intCount = client.getIntStackSize();
		if (ints == null || intCount < 3)
		{
			return;
		}
		ChatMessageType type = ChatMessageType.of(ints[intCount - 2]);
		MessageNode node = client.getMessages().get(ints[intCount - 1]);
		if (node != null && drops(type, node.getName()))
		{
			ints[intCount - 3] = 0;
		}
	}

	void clear()
	{
		hiddenSpeakers.clear();
	}

	static boolean isPublic(ChatMessageType type)
	{
		return type == ChatMessageType.PUBLICCHAT || type == ChatMessageType.AUTOTYPER;
	}

	/** A name as the game compares them: no tags or icons, spaces made plain, any case. */
	static String standard(String name)
	{
		return Text.toJagexName(Text.removeTags(name)).toLowerCase();
	}

	private void remember(String name)
	{
		hiddenSpeakers.remove(name);
		hiddenSpeakers.add(name);
		while (hiddenSpeakers.size() > REMEMBERED)
		{
			String oldest = hiddenSpeakers.iterator().next();
			hiddenSpeakers.remove(oldest);
		}
	}

	private Player find(String name)
	{
		WorldView top = client.getTopLevelWorldView();
		if (top == null)
		{
			return null;
		}
		Player p = find(top, name);
		for (WorldView boat : top.worldViews())
		{
			if (p == null && boat != null)
			{
				p = find(boat, name);
			}
		}
		return p;
	}

	private static Player find(WorldView world, String name)
	{
		for (Player p : world.players())
		{
			if (p != null && p.getName() != null && standard(p.getName()).equals(name))
			{
				return p;
			}
		}
		return null;
	}
}

package com.grant9008.personalspace;

import java.util.ArrayList;
import java.util.List;

/**
 * Turns a {@link Snapshot} into plain-English status for the sidebar: one headline saying whether
 * the plugin is working and, if not, what to do; a list of individual checks; and a text report
 * that can be copied and pasted when asking for help. Pure logic, unit tested.
 */
final class StatusSummary
{
	enum Level
	{
		OK,
		WAITING,
		PAUSED,
		PROBLEM
	}

	static final class Headline
	{
		final Level level;
		final String title;
		final String detail;

		Headline(Level level, String title, String detail)
		{
			this.level = level;
			this.title = title;
			this.detail = detail;
		}
	}

	static final class Check
	{
		final Level level;
		final String label;
		final String value;

		Check(Level level, String label, String value)
		{
			this.level = level;
			this.label = label;
			this.value = value;
		}
	}

	private StatusSummary()
	{
	}

	static Headline headline(Snapshot s)
	{
		if (!s.active)
		{
			return new Headline(Level.PAUSED, "Off",
				"Flip the switch above to spread out crowds again.");
		}
		if (s.gate == Snapshot.Gate.NOT_LOGGED_IN)
		{
			return new Headline(Level.WAITING, "Waiting for you to log in", "Crowds are spread out once you're in game.");
		}
		if (s.gate != Snapshot.Gate.SAFE)
		{
			return new Headline(Level.PAUSED, "Paused for safety",
				s.gate.label + ". Everyone is shown where they really stand until then.");
		}
		if (s.renderer == null)
		{
			return new Headline(Level.PROBLEM, "Needs the GPU plugin",
				s.hdEnabled
					? "117 HD is switched on but isn't running. Check it in RuneLite's plugin list."
					: "Press Turn on GPU above, or turn on 117 HD in RuneLite's plugin list.");
		}
		if (!s.hooked)
		{
			return new Headline(Level.PROBLEM, "Couldn't connect",
				"Turn Personal Space off and on again in the plugin list.");
		}
		if (s.noPlayerDrawsSustained)
		{
			return new Headline(Level.PROBLEM, "Something's not right",
				"Players aren't coming through. Open Troubleshooting below and press Copy report.");
		}

		if (s.mode == PersonalSpaceConfig.Mode.TEST_SHIFT_ME)
		{
			if (s.nudgedDrawsPerSec > 0)
			{
				return new Headline(Level.OK, "Test mode is on",
					"Your character is drawn " + s.testOffset + " units to the east. Turn test mode off in Troubleshooting when you're done.");
			}
			if (s.testOffset == 0)
			{
				return new Headline(Level.WAITING, "Test mode is on",
					"The test distance is 0. Drag the slider in Troubleshooting to see your character move.");
			}
			if (s.nothingMovedSustained)
			{
				return new Headline(Level.PROBLEM, "Test mode isn't moving you",
					"Open Troubleshooting below and press Copy report.");
			}
			return new Headline(Level.WAITING, "Test mode is on", "Moving your character now.");
		}

		if (s.stackedTiles == 0)
		{
			return new Headline(Level.WAITING, "No crowds here",
				"When players stand on the same tile, they'll be spread out automatically.");
		}
		if (s.nudgedDrawsPerSec + s.revealedDrawsPerSec > 0)
		{
			return new Headline(Level.OK, "Spreading " + plural(s.moving, "player") + " on " + plural(s.stackedTiles, "tile"),
				"Crowded tiles are opened up so you can see everyone.");
		}
		if (s.nothingMovedSustained)
		{
			return new Headline(Level.PROBLEM, "Something's not right",
				"Crowds were found but nobody was spread out. Open Troubleshooting below and press Copy report.");
		}
		return new Headline(Level.WAITING, "Found " + plural(s.stackedTiles, "crowded tile"), "Spreading them out now.");
	}

	static List<Check> checks(Snapshot s)
	{
		List<Check> out = new ArrayList<>();
		out.add(new Check(s.active ? Level.OK : Level.PAUSED, "Effect", s.active ? "On" : "Paused"));
		boolean loggedIn = s.gate != Snapshot.Gate.NOT_LOGGED_IN;
		out.add(new Check(loggedIn ? Level.OK : Level.WAITING, "Logged in", loggedIn ? "Yes" : "No"));
		if (loggedIn)
		{
			out.add(new Check(s.gate == Snapshot.Gate.SAFE ? Level.OK : Level.PAUSED, "Safety", s.gate.label));
		}
		out.add(new Check(s.renderer != null ? Level.OK : Level.PROBLEM, "Renderer", s.renderer != null ? s.renderer : "None (turn on GPU)"));
		// Not being connected is only a problem once you're in the world: we deliberately stay out of
		// the renderer's way at the login screen, while it is still starting up.
		out.add(new Check(s.hooked ? Level.OK : (loggedIn && s.renderer != null ? Level.PROBLEM : Level.WAITING),
			"Connected", s.hooked ? "Yes" : "No"));
		if (loggedIn && s.hooked)
		{
			out.add(new Check(s.playerDrawsPerSec > 0 ? Level.OK : (s.noPlayerDrawsSustained ? Level.PROBLEM : Level.WAITING),
				"Players drawn", s.playerDrawsPerSec + " / sec"));
		}
		out.add(new Check(Level.WAITING, "Players nearby", Integer.toString(s.nearby)));
		out.add(new Check(Level.WAITING, "Standing still", Integer.toString(s.still)));
		out.add(new Check(s.stackedTiles > 0 ? Level.OK : Level.WAITING, "Stacked tiles", Integer.toString(s.stackedTiles)));
		out.add(new Check(s.moving > 0 ? Level.OK : Level.WAITING, "Being spread", Integer.toString(s.moving)));
		boolean anyDrawn = s.nudgedDrawsPerSec + s.revealedDrawsPerSec > 0;
		Level drawnLevel = anyDrawn ? Level.OK : (s.nothingMovedSustained ? Level.PROBLEM : Level.WAITING);
		out.add(new Check(drawnLevel, "Drawn moved", s.nudgedDrawsPerSec + " / sec"));
		if (s.mode == PersonalSpaceConfig.Mode.SPREAD)
		{
			out.add(new Check(drawnLevel, "Hidden shown", s.revealedDrawsPerSec + " / sec"));
		}
		if (s.playersInOtherCalls > 0 || s.offThreadDraws > 0 || s.revealErrors > 0 || s.skippedIds > 0)
		{
			out.add(new Check(Level.PROBLEM, "Oddities", "see report"));
		}
		return out;
	}

	static String report(Snapshot s)
	{
		Headline h = headline(s);
		StringBuilder b = new StringBuilder();
		b.append("Personal Space ").append(s.pluginVersion).append(" report\n");
		b.append("Status: ").append(h.level).append(" - ").append(h.title).append('\n');
		b.append("Settings: effect ").append(s.active ? "on" : "paused")
			.append(", mode ").append(s.mode)
			.append(", arrangement ").append(s.arrangement)
			.append(", spacing ").append(s.spacing)
			.append(", max per tile ").append(s.maxStack)
			.append(", move me ").append(yesNo(s.includeLocal))
			.append(", draw me in front ").append(yesNo(s.drawMeInFront))
			.append(", small groups close ").append(yesNo(s.smallGroupsClose))
			.append(", pose ").append(s.pose)
			.append(", names over players ").append(yesNo(s.names))
			.append(", hover shows who ").append(yesNo(s.hover))
			.append(", arrow to their tile ").append(yesNo(s.hoverArrow))
			.append(", hide below level ").append(s.hideBelow <= PersonalSpaceConfig.MIN_HIDE_BELOW ? "off" : String.valueOf(s.hideBelow))
			.append(", hide their chat ").append(yesNo(s.hideChat))
			.append(", pause in combat ").append(yesNo(s.pauseInCombat))

			.append(", test offset ").append(s.testOffset).append('\n');
		b.append("Safety: ").append(s.gate.label).append('\n');
		b.append("Renderer: ").append(s.renderer == null ? "none" : s.renderer)
			.append(", connected ").append(yesNo(s.hooked)).append('\n');
		b.append("Player draws/sec: ").append(s.playerDrawsPerSec)
			.append(", drawn moved/sec: ").append(s.nudgedDrawsPerSec)
			.append(", hidden shown/sec: ").append(s.revealedDrawsPerSec)
			.append(", other-scene draws/sec: ").append(s.sceneMismatchesPerSec)
			.append(", players in other calls (should be 0): ").append(s.playersInOtherCalls)
			.append(", off-thread draws (should be 0): ").append(s.offThreadDraws)
			.append(", reveal errors: ").append(s.revealErrors)
			.append(", walk frames drawn: ").append(s.walkDraws)
			.append(", drawn far to near: ").append(s.orderedDraws)
			.append(" (by their lean: ").append(s.leanedDraws).append(')')
			.append(", frames not ordered (should be 0): ").append(s.passMissedFrames)
			.append(", hidden in your way: ").append(s.hiddenInYourWay)
			.append(", crowd drops: ordered ").append(s.keptDips)
			.append(" probe ").append(s.probeBlackouts)
			.append(" thrown away ").append(s.droppedUndrawn)
			.append(" plan ").append(s.planDips)
			.append(" switched off ").append(s.resets)
			.append(" hooked ").append(s.shimInstalls)
			.append(", tile blinks: nobody in the middle ").append(s.blinkNoMiddle)
			.append(" unconfirmed ").append(s.blinkUnconfirmed)
			.append(" other plugins ").append(s.blinkOthersHid)
			.append(" moved ").append(s.blinkMoved)
			.append(" other ").append(s.blinkOther)
			.append(", held with no model ").append(s.keptWithoutModel)
			.append(", no walk (busy): ").append(s.walkSkippedBusy)
			.append(", no walk (animation not loaded): ").append(s.walkSkippedNoAnimation)
			.append(", held for confirmation: ").append(s.probeHeld)
			.append(", never confirmed: ").append(s.probeGaveUp)
			.append(", tile shape changes: ").append(s.shapeChanges)
			.append(", spot moves: ").append(s.spotMoves)
			.append(", no draws sustained: ").append(yesNo(s.noPlayerDrawsSustained))
			.append(", nothing moved sustained: ").append(yesNo(s.nothingMovedSustained)).append('\n');
		b.append("Nearby: ").append(s.nearby)
			.append(", on boats: ").append(s.aboard)
			.append(", standing still: ").append(s.still)
			.append(", stacked tiles: ").append(s.stackedTiles)
			.append(", being spread: ").append(s.moving)
			.append(", skipped ids: ").append(s.skippedIds)
			.append(", stacked but not shown by the game: ").append(s.unseenStacked).append('\n');
		b.append("Your tile: ").append(s.yourShape == null ? "not being spread" : s.yourShape).append('\n');
		b.append("Nearest spread tile: ").append(s.nearestTile == null ? "none" : s.nearestTile).append('\n');
		return b.toString();
	}

	private static String plural(int n, String word)
	{
		return n + " " + word + (n == 1 ? "" : "s");
	}

	private static String yesNo(boolean b)
	{
		return b ? "yes" : "no";
	}
}

package com.grant9008.personalspace;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

/**
 * Settings. Everything here can also be changed from the Personal Space sidebar panel, which
 * writes through the same config keys, so the two always agree.
 */
@ConfigGroup(PersonalSpaceConfig.GROUP)
public interface PersonalSpaceConfig extends Config
{
	String GROUP = "personalspace";

	String KEY_ACTIVE = "active";
	String KEY_ARRANGEMENT = "arrangement";
	String KEY_MODE = "mode";
	String KEY_SPACING = "spacingUnits";
	String KEY_MAX_STACK = "maxStack";
	String KEY_INCLUDE_LOCAL = "includeLocalPlayer";
	String KEY_SMALL_GROUPS_CLOSE = "smallGroupsClose";
	String KEY_POSE = "smallGroupPose";
	String KEY_PAUSE_IN_COMBAT = "pauseInCombat";
	String KEY_DRAW_ME_IN_FRONT = "drawMeInFront";
	String KEY_NAMES = "namesFollowPlayers";
	String KEY_HOVER = "hoverShowsWho";
	String KEY_HOVER_ARROW = "hoverArrow";
	String KEY_HIDE_BELOW = "hideBelowLevel";
	String KEY_HIDE_CHAT = "hideTheirChat";
	/** Nobody is below level 3, where everyone starts, so up to 3 the filter hides nobody: it's off. */
	int MIN_HIDE_BELOW = 3;
	int MAX_HIDE_BELOW = 126;
	String KEY_TEST_OFFSET = "testOffset";
	String KEY_SHOW_SIDEBAR = "showSidebarButton";

	int MIN_STACK = 2;
	int MAX_STACK = 16;
	int DEFAULT_STACK = 5;
	int MIN_TEST_OFFSET = 0;
	int MAX_TEST_OFFSET = 64;

	/** Spacing between players, in local units (128 is one tile). */
	int MIN_SPACING = 16;
	int MAX_SPACING = 256;
	int SPACING_CLOSE = 40;
	int SPACING_NORMAL = 128;
	/** Two tiles apart: what looks best in a big Grand Exchange crowd, so it's the default. Banks, fires and anvils stay closer on their own. */
	int SPACING_WIDE = 256;
	/**
	 * The slider sets the spacing for a full crowd. Two players on a tile stand at most this far apart
	 * (a bit over half a tile), and bigger groups spread further, reaching the slider's spacing at
	 * {@link #FULL_CROWD} players: two people two tiles apart just look lost.
	 */
	int PAIR_SPACING = 72;
	int FULL_CROWD = 8;
	/**
	 * With Auto-space on, people at a bank counter or row of booths stand at most this far apart,
	 * whatever the slider says: a body's width, so seen from the side nobody runs into the person
	 * beside them, as they did at 42. Close enough to read as a busy bank rather than a queue; much
	 * wider and a short stretch of counter runs out of room, leaving people stacked in the middle.
	 */
	int COUNTER_SPACING = 48;
	/**
	 * How close a line shared by several booths or along a riverbank closes up when it gets busy
	 * (more than {@code CrowdPlanner.ROOMY_LINE_MAX} people on one of its tiles), with Auto-space on.
	 * Otherwise it keeps {@link #COUNTER_SPACING}: at 42 bodies and capes ran into each other seen
	 * from the side, but a packed line only has so much counter, and at 50 one ran out of spots and
	 * left people hidden in the middle.
	 */
	int LINE_SPACING = 42;
	/** Smart keeps people around a fire at most this far apart, whatever the slider says. */
	int FIRE_SPACING = 46;

	enum Mode
	{
		SPREAD("Spread stacked players"),
		TEST_SHIFT_ME("Test: shift my character");

		private final String label;

		Mode(String label)
		{
			this.label = label;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	/** How two or three players standing together in the open are turned. */
	enum Pose
	{
		NATURAL("Natural"),
		ANGLED("Angled"),
		FACING("Facing");

		private final String label;

		Pose(String label)
		{
			this.label = label;
		}

		@Override
		public String toString()
		{
